using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Windows.Threading;
namespace SoloCamera.Windows;
public static class Program {
 [STAThread] public static void Main(string[] args){try{if((args.Length==3||args.Length==4)&&args[0]=="--screen-live-test"){ScreenLiveTest.Run(args[1],args[2],args.Length==4?args[3]:null).GetAwaiter().GetResult();return;}if(args.Length==3&&args[0]=="--obs-diagnostics"){ObsDiagnostics.Run(args[1],args[2]).GetAwaiter().GetResult();return;}if(args.Length==3&&args[0]=="--qr-integration-test"){QrIntegrationTest.Run(args[1],args[2]).GetAwaiter().GetResult();return;}if(args.Length==2&&args[0]=="--list-cameras"){File.WriteAllLines(args[1],CameraDevices.List());return;}if(args.Length==4&&args[0]=="--integration-test"){IntegrationTest.Run(args[1],args[2],args[3]).GetAwaiter().GetResult();return;}if(args.Length>0&&args[0]=="--self-test"){SelfTest.Run(args.Length>1?args[1]:"test-results.txt").GetAwaiter().GetResult();return;}new Application().Run(new MainWindow(args.Contains("--pair"),args.Contains("--restore-obs")));}catch(Exception e){MessageBox.Show(e.Message,"Solo Camera");}}
}
public sealed class MainWindow:Window {
 readonly CheckBox usb=new(){Content="Use USB feed after QR pairing (USB debugging required)",Foreground=Brushes.White,Margin=new Thickness(0,8,0,8)};readonly List<int> usbPorts=new();
 readonly PhoneConnection[] cameras=Enumerable.Range(0,4).Select(_=>new PhoneConnection()).ToArray();readonly LocalFeedServer server;readonly Image[] previews=new Image[4];readonly TextBlock[] statuses=new TextBlock[4];readonly long[] sequences=new long[4];readonly DispatcherTimer timer=new(){Interval=TimeSpan.FromMilliseconds(33)};ObsBridge? obs;bool startedWebcam;readonly TextBlock message=new(){Text="Connect a phone, then set up OBS Virtual Camera.",TextWrapping=TextWrapping.Wrap,Margin=new Thickness(8)};readonly PasswordBox obsPassword=new(){Width=200};readonly TextBox obsPort=new(){Text="4455",Width=65};
 public MainWindow(bool pairOnOpen=false,bool restoreObs=false){Title="Solo Camera · Windows Webcam";Width=1100;Height=850;MinWidth=850;MinHeight=650;Background=new SolidColorBrush(Color.FromRgb(19,22,29));Foreground=Brushes.White;server=new(cameras);var root=new StackPanel{Margin=new Thickness(22)};Content=new ScrollViewer{Content=root};root.Children.Add(new TextBlock{Text="Cameras and screen demos. Live in OBS.",FontSize=28,FontWeight=FontWeights.Bold});root.Children.Add(new TextBlock{Text="Camera: open Webcam on your phone. Screen demo: enable Live screen demo in Screen recording, start, then Pair Windows. Scan this receiver’s Pair by QR code. Use the same Wi-Fi or hotspot. Grid audio comes from slot 1.",Margin=new Thickness(0,8,0,16),TextWrapping=TextWrapping.Wrap});root.Children.Add(usb);var grid=new Grid();grid.ColumnDefinitions.Add(new());grid.ColumnDefinitions.Add(new());grid.RowDefinitions.Add(new());grid.RowDefinitions.Add(new());root.Children.Add(grid);
 for(int i=0;i<4;i++){int slot=i;var card=new StackPanel{Margin=new Thickness(10)};var border=new Border{Child=card,Background=new SolidColorBrush(Color.FromRgb(31,36,46)),CornerRadius=new CornerRadius(12),Margin=new Thickness(5)};Grid.SetColumn(border,i%2);Grid.SetRow(border,i/2);grid.Children.Add(border);card.Children.Add(new TextBlock{Text=$"CAMERA {i+1}",FontWeight=FontWeights.Bold});previews[i]=new Image{Height=140,Stretch=Stretch.Uniform};card.Children.Add(previews[i]);statuses[i]=new TextBlock{Text="Not connected",TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,4,0,4)};card.Children.Add(statuses[i]);var manual=new StackPanel();card.Children.Add(new Expander{Header="Manual pairing",Foreground=Brushes.Silver,Content=manual});var ip=new TextBox{ToolTip="Phone IP address or complete solocamera pairing code",Margin=new Thickness(0,3,0,3)};manual.Children.Add(new TextBlock{Text="Phone address / pairing code",FontSize=12});manual.Children.Add(ip);var key=new PasswordBox{ToolTip="32-character key from Manual details"};manual.Children.Add(new TextBlock{Text="Pairing key",FontSize=12});manual.Children.Add(key);var buttons=new WrapPanel();card.Children.Add(buttons);AddButton(buttons,"Pair by QR",()=>{if(cameras[slot].Running){message.Text="Disconnect this camera before pairing another phone.";return;}var dialog=new PairingWindow((host,secret)=>{ConnectPhone(slot,host,secret);key.Clear();ip.Text=host;}){Owner=this};dialog.ShowDialog();});AddButton(manual,"Connect manually",()=>{try{string address=ip.Text.Trim(),secret=key.Password.Trim();if(address.StartsWith("solocamera:1:")){var parts=address.Split(':');if(parts.Length!=4)throw new ArgumentException("Invalid pairing code");address=parts[2];secret=parts[3];}ConnectPhone(slot,address,secret);key.Clear();}catch(Exception e){message.Text=e.Message;}});AddButton(buttons,"Disconnect",()=>cameras[slot].Disconnect());}
 var modes=new WrapPanel();root.Children.Add(modes);AddButton(modes,"▦ Four-camera grid",()=>server.Mode=-1);for(int i=0;i<4;i++){int slot=i;AddButton(modes,$"Camera {i+1}",()=>server.Mode=slot);}root.Children.Add(new TextBlock{Text="OBS Virtual Camera",FontSize=20,Margin=new Thickness(0,12,0,4)});root.Children.Add(new TextBlock{Text="In OBS: Tools → WebSocket Server Settings → Enable WebSocket server. Enter its port and password below.",TextWrapping=TextWrapping.Wrap});var auth=new WrapPanel{Margin=new Thickness(0,8,0,4)};root.Children.Add(auth);auth.Children.Add(new TextBlock{Text="Port ",VerticalAlignment=VerticalAlignment.Center});auth.Children.Add(obsPort);auth.Children.Add(new TextBlock{Text="  Password ",VerticalAlignment=VerticalAlignment.Center});auth.Children.Add(obsPassword);AddAsyncButton(auth,"Connect OBS",async()=>{obs?.Dispose();obs=new();await obs.Connect(int.Parse(obsPort.Text),obsPassword.Password);obsPassword.Clear();message.Text="OBS connected. Set up scenes, then start the webcam.";});var actions=new WrapPanel();root.Children.Add(actions);AddAsyncButton(actions,"Reconnect existing OBS feeds",RestoreObs);AddAsyncButton(actions,"Set up webcam scenes",async()=>{await RequireObs().Setup(server.Url);message.Text="Webcam scenes ready. Select Camera 1–4 or the grid above.";});AddAsyncButton(actions,"Start webcam",async()=>{await RequireObs().StartWebcam();startedWebcam=true;message.Text="Webcam on. In OBS, Zoom or your browser, choose OBS Virtual Camera. Virtual Camera sends video only. Screen-demo sound stays in the OBS mixer; Zoom needs a separate audio input.";});AddAsyncButton(actions,"Stop webcam",async()=>{await RequireObs().Request("StopVirtualCam");startedWebcam=false;message.Text="Webcam stopped.";});AddButton(actions,"Copy clean feed URL",()=>{Clipboard.SetText(server.Url);message.Text="Copied. Add an OBS Browser source, enable Control audio via OBS, and set dimensions to your OBS canvas.";});root.Children.Add(message);root.Children.Add(new TextBlock{Text="USB / HDMI cameras can be added as Video Capture Device sources in OBS. Each phone currently supports one monitor connection. Keep this receiver open while using its webcam feed.",TextWrapping=TextWrapping.Wrap,Foreground=Brushes.Silver,Margin=new Thickness(8)});
 Loaded+=async(_,_)=>{if(restoreObs)await RestoreObs();if(pairOnOpen)new PairingWindow((host,secret)=>ConnectPhone(0,host,secret)){Owner=this}.ShowDialog();};timer.Tick+=(_,_)=>Refresh();timer.Start();Closing+=async(_,_)=>{timer.Stop();if(startedWebcam&&obs!=null)try{await obs.Request("StopVirtualCam");}catch{}obs?.Dispose();server.Dispose();foreach(var camera in cameras)camera.Dispose();foreach(int port in usbPorts)UsbForward.Remove(port);};}
 async Task RestoreObs(){ObsBridge? bridge=null;try{string path=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),"obs-studio","plugin_config","obs-websocket","config.json");using var config=System.Text.Json.JsonDocument.Parse(await File.ReadAllTextAsync(path));if(!config.RootElement.GetProperty("server_enabled").GetBoolean())throw new IOException("Enable the OBS WebSocket server first.");bridge=new ObsBridge();await bridge.Connect(config.RootElement.GetProperty("server_port").GetInt32(),config.RootElement.GetProperty("server_password").GetString()??"");foreach(string operation in new[]{"GetRecordStatus","GetStreamStatus"})if((await bridge.Request(operation)).GetProperty("outputActive").GetBoolean())throw new IOException("Stop OBS recording/streaming before reconnecting feeds.");int updated=0;var inputs=(await bridge.Request("GetInputList")).GetProperty("inputs");foreach(var input in inputs.EnumerateArray()){if(input.GetProperty("inputKind").GetString()!="browser_source")continue;string name=input.GetProperty("inputName").GetString()!;var settings=(await bridge.Request("GetInputSettings",new{inputName=name})).GetProperty("inputSettings");if(!settings.TryGetProperty("url",out var value)||!Uri.TryCreate(value.GetString(),UriKind.Absolute,out var url)||url.Host!="127.0.0.1"||!System.Text.RegularExpressions.Regex.IsMatch(url.AbsolutePath,"^/[a-f0-9]{48}/feed$"))continue;await bridge.Request("SetInputSettings",new{inputName=name,inputSettings=new{url=server.Url+url.Query,reroute_audio=true,fps=30,fps_custom=true,shutdown=true},overlay=true});updated++;}obs?.Dispose();obs=bridge;bridge=null;message.Text=updated>0?$"Reconnected {updated} OBS feeds. Pair your phone to go live.":"OBS connected. Click Set up webcam scenes to add the camera feed.";}catch(Exception e){message.Text="OBS reconnection: "+e.Message;}finally{bridge?.Dispose();}} ObsBridge RequireObs()=>obs??throw new InvalidOperationException("Connect OBS first.");
 void ConnectPhone(int slot,string host,string secret){try{if(usb.IsChecked==true){var parts=secret.Split(':');int remote=parts.Length==2?int.Parse(parts[1]):48731;var endpoint=UsbForward.Open(remote);usbPorts.Add(endpoint.Port);cameras[slot].Connect(endpoint.Host,parts[0],endpoint.Port);}else cameras[slot].Connect(host,secret);}catch(Exception e){message.Text=e.Message;}}
 void Refresh(){for(int i=0;i<4;i++){statuses[i].Text=cameras[i].Status;var f=cameras[i].Latest;if(f==null||(DateTime.UtcNow-f.At).TotalSeconds>2){previews[i].Source=null;continue;}if(sequences[i]==f.Sequence)continue;sequences[i]=f.Sequence;try{using var stream=new MemoryStream(f.Jpeg);var image=new BitmapImage();image.BeginInit();image.CacheOption=BitmapCacheOption.OnLoad;image.DecodePixelWidth=480;image.StreamSource=stream;image.EndInit();image.Freeze();previews[i].Source=image;previews[i].LayoutTransform=new RotateTransform(f.Rotation);}catch{statuses[i].Text="Unable to decode camera frame";}}}
 static void AddButton(Panel parent,string label,Action action){var b=new Button{Content=label,Padding=new Thickness(12,7,12,7),Margin=new Thickness(3)};b.Click+=(_,_)=>action();parent.Children.Add(b);}
 void AddAsyncButton(Panel parent,string label,Func<Task> action){var b=new Button{Content=label,Padding=new Thickness(12,7,12,7),Margin=new Thickness(3)};b.Click+=async(_,_)=>{b.IsEnabled=false;try{await action();}catch(Exception e){message.Text=e.Message;}finally{b.IsEnabled=true;}};parent.Children.Add(b);}
}









